(window.TNQ=window.TNQ||[]).push({"terms":{"도덕적 해이":{"d":"계약 뒤 한쪽의 행동을 상대가 볼 수 없어, 위험을 피하려는 노력을 줄이는 현상.","r":["유인설계","비대칭정보"]},"유인설계":{"d":"상대가 원하는 방향으로 행동하도록 보상과 처벌의 구조를 짜는 일.","r":["도덕적 해이"]},"역선택":{"d":"거래 전 정보가 부족한 쪽이 위험이 큰 상대를 골라 거래하게 되는 현상.","r":["비대칭정보","도덕적 해이"]},"비대칭정보":{"d":"거래 당사자 한쪽만 상품의 질이나 행동을 알고 있는 상태.","r":["역선택","도덕적 해이"]},"위험 프리미엄":{"d":"위험을 떠안는 대가로 기대수익에서 확실성 등가 수익을 뺀 금액.","r":["확실성 등가 수익"]},"확실성 등가 수익":{"d":"위험한 투자의 기대효용과 같은 효용을 주는 확실한 수익 금액.","r":["위험 프리미엄"]},"규모의 불경제":{"d":"생산량이 늘어날수록 평균비용이 오르는 현상.","r":["한계비용"]},"한계비용":{"d":"생산량을 한 단위 늘릴 때 추가로 드는 비용.","r":["규모의 불경제"]},"승수 효과":{"d":"독립적인 지출이 한 번 늘면 소득이 그보다 몇 배로 늘어나는 파급 효과.","r":[]},"토빈의 q":{"d":"기업 주식의 시장가치를 자본재 대체비용으로 나눈 값으로 투자 결정의 기준.","r":["사용자비용"]},"한계생산":{"d":"생산요소를 한 단위 더 투입할 때 늘어나는 생산량.","r":["사용자비용"]},"사용자비용":{"d":"자본을 한 기간 사용하는 데 드는 비용으로 이자와 감가상각을 합한 것.","r":["한계생산","토빈의 q"]},"수익률곡선":{"d":"만기가 다른 채권의 수익률을 만기 순서대로 이은 곡선.","r":[]},"헤지":{"d":"서로 반대로 움직이는 자산을 묶어 손실 위험을 줄이는 투자 방법.","r":[]},"초과누진세율":{"d":"소득이 일정 구간을 넘는 부분마다 더 높은 세율을 매기는 방식.","r":[]},"가격 신축성":{"d":"수요와 공급에 따라 가격과 임금이 자유롭게 변하는 성질.","r":["비자발적 실업"]},"비자발적 실업":{"d":"현재 임금에서 일할 의사가 있어도 일자리를 얻지 못한 상태.","r":["가격 신축성"]},"합리적 기대":{"d":"경제주체가 이용할 수 있는 정보를 모두 써서 미래를 예상한다는 가설.","r":["시장청산"]},"시장청산":{"d":"가격이 조정되어 시장의 수요량과 공급량이 항상 일치하는 상태.","r":["합리적 기대","가격 신축성"]},"황금률 자본량":{"d":"균제상태에서 1인당 소비를 가장 크게 하는 자본량.","r":["균제상태"]},"균제상태":{"d":"1인당 자본량 등 주요 변수가 더 이상 변하지 않는 장기 균형 상태.","r":["황금률 자본량"]},"이자율 평형":{"d":"국내외 금융자산의 기대수익률이 같아지도록 금리차와 환율 변화가 맞춰진다는 조건.","r":["순수출"]},"인적자본":{"d":"교육과 훈련으로 노동자에게 쌓인 지식과 기능.","r":[]},"순수출":{"d":"수출액에서 수입액을 뺀 값.","r":["이자율 평형"]}},"notes":{"0과 1 사이의 값을 갖는다":"소득이 한 단위 늘 때 소비가 늘어나는 비율이라 0과 1 사이에 놓입니다.","2011년에서 2025까지 A의 구매력은 증가했다":"구매력은 같은 소득으로 살 수 있는 양이므로 물가보다 소득이 더 올랐다는 말입니다.","X재 소비량이 Y재 소비량보다 1 크다":"X재를 Y재보다 한 단위 더 소비한다는 비교로, 소비량의 차이만 알려 줍니다.","가격이 분리 공급할 때의 두 번째 시장의 가격보다 높다":"하나의 값으로 통합 공급하면 그 값이 분리 공급의 두 번째 시장 값을 웃돕니다.","개당 10의 세금을 부과하는 경우":"수요자에게 10을 부과하면 수요곡선이 10만큼 아래로 이동하여 균형이 바뀝니다.","경상수지 균형 하에서 민간저축이 증가":"경상수지가 균형이면 민간저축에서 투자를 뺀 값이 재정적자와 같아지는 관계가 성립합니다.","국내와 해외 금융자산이 완전대체재임을 가정한다":"투자자가 두 나라 자산을 수익만 보고 구별 없이 바꿀 수 있다고 보는 가정이에요.","국내 이자율이 해외 이자율보다 높으면 국내 통화 가치가 하락할 것으로 기대된다":"금리차를 환율 변화가 상쇄하지 않으면 자본이 한쪽으로 몰리므로 통화 약세가 기대됩니다.","규모의 불경제이고, 한계비용은 증가추세에 있다":"생산량이 늘수록 평균비용이 오르는 구간이며, 추가 생산에 드는 비용도 커집니다.","균제상태의 1인당 자본량이 황금률 자본량보다 작을 때":"현재 자본이 소비를 극대화하는 수준에 못 미치는 경우를 가리킵니다.","균형국민소득은 잠재 GDP와 일치한다":"세이의 법칙에서는 공급이 수요를 만들어 항상 완전고용 수준의 생산이 이뤄집니다.","기대수익과 확실성 등가 수익의 차이를 위험 프리미엄이라고 한다":"위험을 감수하는 대가로 요구하는 금액이 기대수익에서 확실성 등가를 뺀 값입니다.","기업들의 진입과 퇴출이 허용되는 장기에서 시장 균형가격은 40보다 낮다":"장기에는 진입과 퇴출으로 초과이윤이 사라져 가격이 평균비용 수준까지 내려옵니다.","노동시장에서 가격 신축성을 가정하여 비자발적 실업이 존재하지 않는다":"임금이 자유롭게 변해 노동시장이 항상 청산되므로 일할 의사가 있는 사람은 모두 취업합니다.","단체보험, 강제보험은 역선택의 문제를 완화시킨다":"가입자를 모두 묶으면 위험이 높은 사람만 가입하는 쏠림이 사라져 역선택이 줄어듭니다.","대표적 새고전학파 이론으로 화폐 정책의 역할을 생략하였다":"기술충격 같은 실물 요인으로 경기변동을 설명하기에 화폐의 역할을 모형에서 뺐습니다.","도덕적 해이를 방지하기 위한 장치를 고안하는 일":"계약 뒤 상대가 몰래 하는 행동을 막을 보상과 감시의 구조를 짜는 작업을 가리킵니다.","독립지출의 승수 효과가 커진다":"투자가 소득에 반응해 늘면 소득 증가가 더 증폭되어 독립지출의 승수가 커집니다.","명목소득에 과세하고 초과누진세율이 적용되는 경우 인플레이션율의 상승은 실질 조세부담을 상승시킨다":"물가만큼 명목소득이 올라도 더 높은 세율 구간에 들어가 실질로 내는 세금이 늘어납니다.","물가상승률이 예상보다 높은 경우 실질소득의 감소로 고통을 받는다":"연금액이 명목으로 고정돼 있어 물가가 오르면 같은 돈으로 살 수 있는 양이 줄어듭니다.","비대칭정보로 인해 발생하는 문제이다":"거래 전에 한쪽만 아는 정보 때문에 위험한 상대가 거래에 몰리는 문제가 생깁니다.","생산비의 감소가 투자비용보다 크다":"투자로 줄어드는 생산비가 투자에 든 비용을 넘으므로 투자하면 이익이 남습니다.","생산에서 저축을 뺀 값은 황금률 자본량에서 최대화된다":"생산에서 저축을 뺀 값이 소비이므로 황금률 자본량이 소비를 가장 크게 하는 자본량이에요.","성과에 대한 유인부여는 도덕적 해이의 문제를 완화 시킨다":"성과에 따라 보상하면 대리인이 노력하도록 이끌려 도덕적 해이가 줄어듭니다.","소득이 증가함에 따라 감소한다":"기초소비가 있어 소득이 커질수록 소비가 소득에서 차지하는 비중이 낮아집니다.","소비자물가를 구성하는 재화 중에서 단기 변동성이 큰 식료품 및 에너지를 제외한 지수":"식료품과 에너지처럼 일시적으로 크게 출렁이는 품목을 빼서 기조적 물가를 보는 지표입니다.","수요자가 지불하는 가격의 상승폭은 공급자가 받는 가격의 하락폭보다 크다":"세금은 탄력성이 낮은 쪽이 더 많이 부담하므로 수요가 공급보다 비탄력적인 경우입니다.","수익률곡선이 우하향할 경우 미래에 경기침체가 예상된다":"장기금리가 단기금리보다 낮다는 것은 앞으로 금리가 내려갈 만큼 경기가 나쁠 것이라는 신호예요.","수입 소비재의 가격 변화는 직접 영향을 미치지 않는다":"GDP 디플레이터는 국내에서 생산한 재화만 대상으로 하므로 수입품 값은 담기지 않습니다.","수입 소비재의 가격 변화는 직접 영향을 미친다":"가계가 소비하는 품목에 수입품이 들어 있으면 그 값이 곧바로 지수에 잡힙니다.","실질이자율의 하락은 주식가격을 상승시켜 투자가 증가한다":"금리가 내려 미래 수익의 현재가치가 커지면 주가가 올라 q가 높아지고 투자가 늘어납니다.","위험회피 투자자는 A보다 B에 더 높은 비중으로 투자한다":"위험회피 투자자는 위험 대비 보상이 나은 자산을 더 많이 담는 선택을 합니다.","유인설계(incentive design)라고 한다":"영어로 incentive design이며, 상대의 행동을 원하는 방향으로 이끌 구조를 설계하는 일입니다.","이자율 평형조건 하에서 국내외 금리차는 기대 환율 변화율과 같다":"금리가 높은 나라 통화는 그만큼 평가절하될 것으로 기대되어 투자 수익이 같아집니다.","인구성장률과 기술진보율이 0%라면":"성장이 없는 경우로 단순화해, 자본이 감가상각분만 메우면 되는 상태를 가정합니다.","인적자본의 축적을 통해 경제성장을 촉진한다":"교육으로 노동자의 숙련과 지식이 쌓이면 같은 노동으로 더 많이 생산할 수 있습니다.","인플레이션율이 정확히 예상되는 경우에도 발생한다":"구두창 비용은 화폐 보유를 줄이려 은행을 자주 오가는 비용이라 예상된 인플레이션에도 생깁니다.","일정 기간 재화 구성이 고정되어 있다":"기준 시점에 정한 소비 품목 묶음을 그대로 두고 값만 바꿔 비교하기 때문입니다.","임금이 상승하더라도 변화하지 않는다":"임금이 올라도 노동공급량이 그대로이므로 노동공급곡선이 수직선인 경우를 말합니다.","자본의 사용자비용이 감소하여 기업의 투자가 증가한다":"이자율이 내리면 자본을 빌려 쓰는 비용이 줄어 투자하는 편이 유리해집니다.","자본의 한계생산물은 감소한다":"자본이 쌓일수록 추가 한 단위가 만드는 생산이 줄어드는 한계생산체감 때문입니다.","자본의 한계생산성은 자본 감가상각률과 일치한다":"황금률에서는 자본 추가분이 만드는 생산이 닳아 없어지는 자본의 비율과 같아집니다.","자본의 한계생산을 증가시켜 투자수요를 증가시킨다":"기술이 나아지면 자본 한 단위가 더 많이 생산하므로 투자수요가 커집니다.","자본재 대체비용 대비 주식의 시장가치가 증가하면":"토빈의 q는 주식의 시장가치를 자본재 대체비용으로 나눈 값이라 분자가 커진 경우입니다.","재원이 부족할 때 공채발행수입으로 충당하는 경우, 물가상승에 따라 실질 공채부담은 가벼워진다":"공채는 명목금액으로 갚으므로 물가가 오르면 갚는 돈의 실질 가치가 줄어듭니다.","재정 수지가 악화되었을 것이다":"저축과 투자의 차이가 재정적자와 같다는 항등식에서 재정수지 악화를 추론합니다.","저축률의 상승은 1인당 자본량을 증가시킨다":"저축이 늘면 투자가 많아져 균제상태의 자본량이 커지고 소비 극대 수준에 가까워집니다.","정부 정책 변화에 따른 경제주체의 행동 변화를 고려하지 않는 거시경제모형":"정책이 바뀌면 사람들의 기대와 행동도 바뀌는데 모형의 계수는 그대로 두는 방식입니다.","정책효과를 분석할 수 없다고 비판하였다":"정책이 바뀌면 사람들의 대응이 바뀌어 과거 관계로는 정책 효과를 예측할 수 없다는 지적이에요.","첫 번째 시장의 가격이 두 번째 시장의 가격보다 높다":"시장마다 값을 따로 매기는 분리 공급이라 첫 번째 시장의 값이 더 높게 형성됩니다.","첫 번째 시장의 공급량이 두 번째 시장의 공급량보다 크다":"분리 공급에서는 첫 번째 시장에 두 번째보다 더 많은 물량을 내놓는 비교입니다.","총수요가 증가할 때 투자가 증가하면":"소득이 늘면 투자도 따라 늘어나는 관계를 조건으로 놓고 승수를 따져 보는 상황입니다.","토빈의 q가 상승하여 투자가 증가한다":"q가 높으면 새 자본재를 사는 비용보다 기업 가치가 더 커서 투자가 늘어납니다.","통화량과 이자율 목표를 동시에 달성하기 어렵다":"화폐수요가 이자율에 반응하므로 통화량을 정하면 이자율이 따라 정해져 둘을 함께 못 잡습니다.","투자자는 기대 수익에 따른 의사결정과 기대효용에 따른 의사결정이 동일하다":"한계효용이 일정하면 효용이 수익에 비례하므로 위험중립형 투자자가 됩니다.","투자자는 위험 회피 성향을 보인다":"한계효용이 체감하면 효용함수가 오목해져 불확실한 수익보다 확실한 수익을 택합니다.","평판과 상표 이미지를 통해 상품시장의 도덕적 해이가 완화될 수 있다":"판매자가 평판을 잃기 싫어 품질을 지키려 하므로 숨은 행동의 문제가 줄어듭니다.","프리드먼(M. Friedman)에 따르면 인플레이션은 언제나 화폐적 현상이다":"물가 상승은 생산 증가보다 통화량이 더 빠르게 늘어난 결과라고 본 통화주의 견해입니다.","한국의 무위험 이자율이 미국의 무위험 이자율보다 높다":"원금 손실 위험이 없는 자산의 수익률이 한국에서 더 높은 상황을 전제로 합니다.","합리적 기대와 시장청산 가정하에 일반균형 거시경제 모형을 제시하였다":"경제주체가 정보를 효율적으로 써서 예측하고 시장이 항상 청산된다고 보아 모형을 세웠습니다.","헤지(hedge) 투자가 가능하다":"두 자산이 정반대로 움직여 한쪽 손실을 다른 쪽 이익이 메우므로 위험을 없앨 수 있습니다.","화폐보다 채권에 대한 사람들의 수요가 증가한다":"채권을 사려는 사람이 늘면 채권 값이 올라 이자율이 떨어지는 방향으로 움직입니다."}});if(window.DIAGRAM&&DIAGRAM.tnFlush)DIAGRAM.tnFlush();
